using System.Collections.Generic;
using ExitClause.CameraSystem;
using ExitClause.Combat;
using ExitClause.Hacking;
using ExitClause.Story;
using UnityEngine;

namespace ExitClause.Systems
{
    /// <summary>
    /// Registry of every ScriptableObject the game needs to look up by id at runtime
    /// (after loading a save, for example). Lives at Resources/GameDatabase.asset and is
    /// regenerated by the Editor data builder.
    /// </summary>
    [CreateAssetMenu(menuName = "Exit Clause/Game Database")]
    public class GameDatabase : ScriptableObject
    {
        public static GameDatabase Instance { get; private set; }

        public CameraSettings cameraSettings;
        public List<MissionDefinition> missions = new List<MissionDefinition>();
        public List<ClueDefinition> clues = new List<ClueDefinition>();
        public List<SuspectDefinition> suspects = new List<SuspectDefinition>();
        public List<ItemDefinition> items = new List<ItemDefinition>();
        public List<WeaponDefinition> weapons = new List<WeaponDefinition>();
        public List<DeviceDefinition> devices = new List<DeviceDefinition>();
        public List<DialogueSequence> dialogues = new List<DialogueSequence>();
        public List<ChoiceDefinition> choices = new List<ChoiceDefinition>();
        public List<EndingDefinition> endings = new List<EndingDefinition>();
        public List<ItemStack> startingItems = new List<ItemStack>();

        [Header("Runtime FX materials")]
        public Material tracerMaterial;
        public Material visionConeMaterial;
        public Material evidenceMaterial;

        public static void Load()
        {
            Instance = Resources.Load<GameDatabase>("GameDatabase");
            if (Instance == null)
            {
                Debug.LogWarning("[GameDatabase] Resources/GameDatabase.asset missing. Run Exit Clause > Build Everything.");
                Instance = CreateInstance<GameDatabase>();
            }
        }

        public MissionDefinition GetMission(string id) => missions.Find(m => m != null && m.id == id);
        public ClueDefinition GetClue(string id) => clues.Find(c => c != null && c.id == id);
        public SuspectDefinition GetSuspect(string id) => suspects.Find(s => s != null && s.id == id);
        public ItemDefinition GetItem(string id) => items.Find(i => i != null && i.id == id);
        public WeaponDefinition GetWeapon(string id) => weapons.Find(w => w != null && w.id == id);
        public DeviceDefinition GetDevice(string id) => devices.Find(d => d != null && d.id == id);
        public DialogueSequence GetDialogue(string id) => dialogues.Find(d => d != null && d.id == id);
        public ChoiceDefinition GetChoice(string id) => choices.Find(c => c != null && c.id == id);
        public EndingDefinition GetEnding(string id) => endings.Find(e => e != null && e.id == id);
    }
}
